(() => {
 const rows = [...document.querySelectorAll('[role="dialog"] [data-slot="checkbox"]')];
 if (rows.length < 2) throw new Error('Need at least two available agents in the isolated fixture');
 const rects = rows.map(row => {
  const content = row.querySelector('[data-slot="checkbox-content"]');
  const control = row.querySelector('[data-slot="checkbox-control"]');
  const count = content?.querySelector('div > span:last-child');
  if (!content || !control || !count || !content.contains(control)) throw new Error('Missing checkbox anatomy');
  const r = row.getBoundingClientRect(), c = content.getBoundingClientRect();
  const padding = parseFloat(getComputedStyle(row).paddingLeft) + parseFloat(getComputedStyle(row).paddingRight);
  if (Math.abs(c.width - (row.clientWidth - padding) * r.width / row.offsetWidth) > 1) throw new Error(`Content is not full width: ${c.width} / ${r.width}`);
  return { left: control.getBoundingClientRect().left, right: count.getBoundingClientRect().right };
 });
 if (rects.some(r => Math.abs(r.left - rects[0].left) > 1 || Math.abs(r.right - rects[0].right) > 1)) throw new Error('Checkboxes/counts are not aligned');
 return rects;
})()

